// Nahrazuje worker DocFX stejného názvu. Jeho lunr nemá češtinu a nehledá bez diakritiky.
import { createSearchIndex, searchIndex } from './search-core.js';

let index;

async function loadIndex() {
  const response = await fetch('../index.json');
  if (!response.ok)
    throw new Error(`Vyhledávací index se nepodařilo načíst: HTTP ${response.status}`);
  index = createSearchIndex(await response.json());
  postMessage({ e: 'index-ready' });
}

onmessage = ({ data }) => {
  if (data?.init && !index) loadIndex().catch(console.error);
  else if (typeof data?.q === 'string' && index)
    postMessage({ e: 'query-ready', d: searchIndex(index, data.q) });
};
